-- Cloud-ready Supabase schema for MC Gal Togoo ERP
create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text not null default '', role text not null default 'viewer');
create table if not exists materials(id uuid primary key default gen_random_uuid(), code text unique not null, name text not null, category text not null, unit text not null, balance numeric not null default 0, need14 numeric not null default 0, price numeric not null default 0, updated_at timestamptz default now());
create table if not exists inventory_transactions(id uuid primary key default gen_random_uuid(), created_at timestamptz default now(), material_code text not null, material_name text not null, txn_type text not null, qty numeric not null, unit text not null, note text default '', created_by uuid references auth.users(id));
create table if not exists daily_plans(plan_date date primary key, people jsonb not null default '{}'::jsonb, menu jsonb not null default '{}'::jsonb, applied jsonb not null default '{}'::jsonb, updated_at timestamptz default now(), updated_by uuid references auth.users(id));
create table if not exists material_requests(id uuid primary key default gen_random_uuid(), request_no text unique not null, branch text not null, warehouse text not null, need_date date not null, status text not null default 'draft', note text default '', created_at timestamptz default now(), created_by uuid references auth.users(id));
create table if not exists material_request_lines(id bigint generated always as identity primary key, request_id uuid references material_requests(id) on delete cascade, material_code text not null, material_name text not null, category text, qty numeric not null, unit text not null, stock_balance numeric not null default 0);
